(() => {
  const heroImage=document.querySelector('.hero .one img');
  heroImage.src='assets/street-model.png';
  heroImage.alt='Featured streetwear look: black hooded layer, cap, wide-leg dark denim and tan boots';
  heroImage.style.objectPosition='center 35%';
  document.querySelector('.hero .one figcaption').textContent='FILE 001 / AFTER DARK UNIFORM';
  const editorial=document.createElement('section');editorial.className='section street-editorial';editorial.id='street-inspiration';
  const refs=[
    {title:'DARK DENIM / SOFT VOLUME',image:'https://i.pinimg.com/originals/cb/78/fe/cb78fea3ac3b16044d264b06da9d7cbc.jpg',source:'https://www.pinterest.com/pin/13792342603355271/',desc:'Oversized hoodie, dark wide-leg denim and silver accents.'},
    {title:'ZIP LAYER / TWO-TONE',image:'https://i.pinimg.com/originals/db/28/b8/db28b87cc796b40e0a645fa416331bfe.jpg',source:'https://uk.pinterest.com/pin/my-aesthetic-in-2025--4644405860616567/',desc:'Loose black zip layer, panelled denim and chunky footwear.'},
    {title:'BLACKOUT / EVERYDAY',image:'https://i.pinimg.com/736x/2c/f1/05/2cf105fd3606dcdb930ea31447964bc5.jpg',source:'https://ph.pinterest.com/pin/774124929850222/',desc:'Tonal black layers, faded jeans and contrasting sneakers.'},
    {title:'DENIM / SILVER DETAILS',image:'https://i.pinimg.com/736x/31/35/3f/31353f14ff24a801c5eb209b24a36ed9.jpg',source:'https://ru.pinterest.com/pin/308707749477144269/',desc:'Dark denim, relaxed hoodie and small metallic accessories.'}
  ];
  editorial.innerHTML=`<div class="editorial-feature"><figure><img loading="lazy" src="assets/street-model.png" alt="Featured model wearing black layered streetwear and oversized dark jeans in a convenience store"><figcaption>LOOK FILE / 11STREET COMMUNITY REFERENCE</figcaption></figure><div><div class="eyebrow">[ STREET FILES / NO DRESS CODE ]</div><h2>AFTER DARK.<br>ALL ATTITUDE.</h2><p>Black layers. Wide denim. A silhouette that does the talking.</p><div class="look-notes"><span>01 / HOODED BLACK LAYER</span><span>02 / LOW-SLUNG WIDE DENIM</span><span>03 / SILVER HARDWARE</span><span>04 / TAN BOOT CONTRAST</span></div><a class="button blue" href="#style-lab">BUILD YOUR OWN ROTATION ↗</a><small>Styling reference supplied by you. Clothing brands, availability and provenance are unverified.</small></div></div><div class="eyebrow">[ PINBOARD / STREETWEAR INSPIRATION ]</div><div class="section-heading"><h2>SAVE THE MOOD.</h2><p>Layers worth studying.<br>Proportions worth remixing.</p></div><p class="demo-note">External Pinterest styling references. These images are inspiration, not 11street inventory or products available to order. Open each original Pin for its source and details.</p><div class="pinboard">${refs.map((r,i)=>`<a class="pin-card" href="${r.source}" target="_blank" rel="noopener noreferrer"><div class="pin-image"><img loading="lazy" referrerpolicy="no-referrer" src="${r.image}" alt="Pinterest outfit reference: ${r.desc}"><span>REF / 00${i+1} ↗</span></div><h3>${r.title}</h3><p>${r.desc}</p><span class="pin-source">VIEW ORIGINAL PIN ↗</span></a>`).join('')}</div>`;
  document.querySelector('.ticker').after(editorial);
  editorial.querySelectorAll('.pin-card img').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;img.parentElement.classList.add('pin-unavailable');const text=document.createElement('p');text.textContent='View this look on Pinterest ↗';img.parentElement.append(text)},{once:true}));
})();
